// Debounce
function debounce(fn, ms) {
    let timeout;
    return function(...args) {
        clearTimeout(timeout);
        timeout = setTimeout(() => fn.apply(this, args), ms);
    };
}

// Throttle
function throttle(fn, ms) {
    let calisiyor = false;
    return function(...args) {
        if (calisiyor) return;
        calisiyor = true;
        setTimeout(() => {
            fn.apply(this, args);
            calisiyor = false;
        }, ms);
    };
}

const input = document.getElementById('input');
const ekleBtn = document.getElementById('ekle');
const liste = document.getElementById('liste');

let gorevler = JSON.parse(localStorage.getItem('gorevler')) || [];

function render() {
    liste.innerHTML = gorevler.map((g, i) =>
        `<li class='${g.tamam ? 'tamam' : ''}' data-index='${i}'>
            ${g.metin} <button class='sil'>Sil</button>
        </li>`
    ).join('');
    localStorage.setItem('gorevler', JSON.stringify(gorevler));
}

ekleBtn.addEventListener('click', () => {
    if (input.value.trim()) {
        gorevler.push({ metin: input.value, tamam: false });
        input.value = '';
        render();
    }
});

liste.addEventListener('click', (e) => {
    const idx = e.target.parentElement.dataset.index;
    if (e.target.classList.contains('sil')) {
        gorevler.splice(idx, 1);
    } else {
        gorevler[idx].tamam = !gorevler[idx].tamam;
    }
    render();
});

input.addEventListener('keydown', (e) => {
    if (e.key === 'Enter') ekleBtn.click();
});

render();
